"use client";

import { formatMoney, type VendorAnalyticsPreview, type VendorDashboardSettings, type VendorDeliveryZone, type VendorEarningsPreview, type VendorStorefrontSettings } from "@mealhrs/domain";
import { Check, MapPinned, Store } from "lucide-react";
import { cloneElement, isValidElement, useId, useState } from "react";
import { Button } from "@/components/ui/button";
import styles from "./vendor-insights.module.css";

export function DeliveryView({ zones }: Readonly<{ zones: readonly VendorDeliveryZone[] }>) {
  const [currentZones, setZones] = useState(zones);
  const [area, setArea] = useState(zones[0]?.areaId ?? "");
  const active = currentZones.find((zone) => zone.areaId === area);
  return <PageHead eyebrow="Fulfillment" title="Delivery zones" description="Choose where the kitchen delivers. These changes are a frontend preview and do not update customer eligibility yet." action={<Button size="sm"><MapPinned size={16}/>Add zone</Button>}><section className={`card ${styles.section}`}><div className={styles.zoneList}>{currentZones.map((zone) => <div className={styles.zone} key={zone.areaId}><div><strong>{zone.name}</strong><span>{formatMoney(zone.deliveryFee)} · {zone.estimate}</span></div><span>{zone.enabled ? "Available" : "Paused"}</span><button className={styles.switch} aria-label={`${zone.enabled ? "Pause" : "Enable"} ${zone.name} delivery`} aria-pressed={zone.enabled} onClick={() => setZones((items) => items.map((item) => item.areaId === zone.areaId ? { ...item, enabled: !item.enabled } : item))}><i/></button></div>)}</div><div className={styles.preview}><div><strong>Eligibility preview</strong><p>{active?.enabled ? `${active.name} customers can see delivery at ${formatMoney(active.deliveryFee)}.` : `${active?.name ?? "This area"} is currently unavailable for delivery.`}</p></div><select aria-label="Preview delivery zone" value={area} onChange={(event) => setArea(event.target.value as typeof area)}>{currentZones.map((zone) => <option key={zone.areaId} value={zone.areaId}>{zone.name}</option>)}</select></div></section></PageHead>;
}

export function EarningsView({ earnings }: Readonly<{ earnings: VendorEarningsPreview }>) { return <PageHead eyebrow="Financial preview" title="Earnings" description={`${earnings.periodLabel}. These figures are illustrative and no payout transfer is connected.`}><div className={styles.grid}><Metric label="Gross sales" value={formatMoney(earnings.grossSales)} detail={earnings.periodLabel}/><Metric label="Platform fees" value={formatMoney(earnings.platformFees)} detail="Preview estimate"/><Metric label="Preview balance" value={formatMoney(earnings.previewBalance)} detail="Not available to withdraw"/></div><section className={`card ${styles.section}`}><h2>How this preview is calculated</h2><div className={styles.money}><div><span>Gross sales</span><strong>{formatMoney(earnings.grossSales)}</strong></div><div><span>Platform fees</span><strong>−{formatMoney(earnings.platformFees)}</strong></div><div><span>Refunds</span><strong>−{formatMoney(earnings.refunds)}</strong></div><div className={styles.total}><span>Preview balance</span><strong>{formatMoney(earnings.previewBalance)}</strong></div></div><div className={styles.notice}>{earnings.note}</div></section></PageHead>; }

export function AnalyticsView({ analytics }: Readonly<{ analytics: VendorAnalyticsPreview }>) { const bars = [{ label: "Mon", value: 54 }, { label: "Tue", value: 38 }, { label: "Wed", value: 70 }, { label: "Thu", value: 61 }, { label: "Fri", value: 88 }, { label: "Sat", value: 100 }, { label: "Sun", value: 78 }]; return <PageHead eyebrow="Performance preview" title="Analytics" description={`${analytics.periodLabel}. Trend visuals use seeded frontend data.`}><div className={styles.grid}><Metric label="Orders" value={String(analytics.orderCount)} detail={analytics.periodLabel}/><Metric label="Average order" value={formatMoney(analytics.averageOrderValue)} detail="Across paid previews"/><Metric label="Repeat customers" value={`${analytics.repeatCustomerRate}%`} detail="Preview estimate"/></div><div className={styles.analytics}><section className={`card ${styles.section}`}><h2>Order rhythm</h2><p>Relative order activity across the week.</p><div className={styles.bars}>{bars.map((bar) => <div className={styles.barRow} key={bar.label}><span>{bar.label}</span><div className={styles.bar}><i style={{ width: `${bar.value}%` }}/></div><strong>{bar.value}</strong></div>)}</div></section><section className={`card ${styles.section}`}><h2>What is working</h2><div className={styles.facts}><Fact label="Top meal" value={analytics.topMeal}/><Fact label="Busiest window" value={analytics.busyWindow}/><Fact label="Next focus" value="Keep Saturday availability visible"/></div></section></div></PageHead>; }

export function StorefrontView({ storefront }: Readonly<{ storefront: VendorStorefrontSettings }>) { const [form, setForm] = useState(storefront); const [saved, setSaved] = useState(false); return <PageHead eyebrow="Customer-facing profile" title="Storefront" description="Control the details customers see before they order."><section className={`card ${styles.section}`}><form className={styles.form} onSubmit={(event) => { event.preventDefault(); setSaved(true); }}><Field label="Kitchen name"><input value={form.displayName} onChange={(event) => setForm({ ...form, displayName: event.target.value })}/></Field><Field label="Handle"><input value={form.handle} onChange={(event) => setForm({ ...form, handle: event.target.value })}/></Field><Field label="Public area"><input value={form.publicArea} onChange={(event) => setForm({ ...form, publicArea: event.target.value })}/></Field><Field label="Kitchen story"><textarea value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })}/></Field><div className={styles.formFoot}><Button type="submit"><Store size={16}/>Save storefront preview</Button>{saved ? <p className={`${styles.formHint} ${styles.saved}`}><Check size={14}/>Saved locally for this preview</p> : <p className={styles.formHint}>No customer-facing change is published in this frontend preview.</p>}</div></form></section></PageHead>; }

export function SettingsView({ settings }: Readonly<{ settings: VendorDashboardSettings }>) { const [form, setForm] = useState(settings); const [saved, setSaved] = useState(false); return <PageHead eyebrow="Workspace" title="Settings" description="Choose how the vendor workspace behaves. These preferences are local to this preview."><section className={`card ${styles.section}`}><div className={styles.setting}><div><h3>New order notifications</h3><p>Show an operational prompt when a new immediate order arrives.</p></div><Toggle value={form.orderNotifications} label="New order notifications" onChange={(value) => setForm({ ...form, orderNotifications: value })}/></div><div className={styles.setting}><div><h3>Meal Drop reminders</h3><p>Surface reminders before a pre-order cutoff.</p></div><Toggle value={form.mealDropReminders} label="Meal Drop reminders" onChange={(value) => setForm({ ...form, mealDropReminders: value })}/></div><div className={styles.form}><Field label="Default preparation estimate"><select value={form.defaultPreparationEstimate} onChange={(event) => setForm({ ...form, defaultPreparationEstimate: event.target.value })}><option>20–30 min</option><option>25–35 min</option><option>35–50 min</option></select></Field><Field label="Support email"><input type="email" value={form.supportEmail} onChange={(event) => setForm({ ...form, supportEmail: event.target.value })}/></Field><div className={styles.formFoot}><Button onClick={() => setSaved(true)}>Save settings preview</Button>{saved ? <p className={`${styles.formHint} ${styles.saved}`}>Preferences saved locally</p> : null}</div></div></section></PageHead>; }

function PageHead({ action, children, description, eyebrow, title }: Readonly<{ action?: React.ReactNode; children: React.ReactNode; description: string; eyebrow: string; title: string }>) { return <div><header className={styles.head}><div><p className={styles.eyebrow}>{eyebrow}</p><h1>{title}</h1><p className={styles.lead}>{description}</p></div>{action}</header><div className="stack-lg">{children}</div></div>; }
function Metric({ detail, label, value }: Readonly<{ detail: string; label: string; value: string }>) { return <article className={`card ${styles.metric}`}><span>{label}</span><strong>{value}</strong><small>{detail}</small></article>; }
function Fact({ label, value }: Readonly<{ label: string; value: string }>) { return <div className={styles.fact}><span>{label}</span><strong>{value}</strong></div>; }
function Field({ children, label }: Readonly<{ children: React.ReactNode; label: string }>) { const id = useId(); const control = isValidElement<{ id?: string }>(children) ? cloneElement(children, { id }) : children; return <div className={styles.field}><label htmlFor={id}>{label}</label>{control}</div>; }
function Toggle({ label, onChange, value }: Readonly<{ label: string; onChange: (value: boolean) => void; value: boolean }>) { return <button className={styles.switch} type="button" aria-label={label} aria-pressed={value} onClick={() => onChange(!value)}><i/></button>; }
